def main(提取文本列表: list[object]) -> dict:
    import re

    def 项目名提取(文本: str) -> str:
        候选 = re.findall(r"(?:项目名称|成果主题|主题)[:：]\s*([^\n，。；]{4,40})", 文本 or "")
        if 候选:
            return 候选[0].strip()
        行 = [l.strip() for l in (文本 or "").split("\n") if 4 <= len(l.strip()) <= 40]
        return 行[0] if 行 else "未识别项目"

    项目列表 = []
    for 项 in (提取文本列表 or []):
        if isinstance(项, dict):
            文件名 = str(项.get("文件名", 项.get("name", "")))
            正文 = str(项.get("内容", 项.get("content", 项.get("text", ""))))
        else:
            文件名, 正文 = "", str(项)
        if not 正文.strip():
            continue
        项目列表.append({"文件名": 文件名, "项目名称": 项目名提取(正文), "正文": 正文})

    if not 项目列表:
        return {"clean_projects": [], "dup_projects": [], "dup_flag_list": "未从申报文件中解析出有效项目内容，请检查上传文件。", "project_count": 0, "dup_report": "无有效项目"}

    库内项目 = [
        {"项目名称": "无人机自主接入平台调试", "关键词": "无人机 低空 司空 接入 平台"},
        {"项目名称": "智能低耗高可靠站台门电磁锁研发及产业化应用", "关键词": "站台门 电磁锁 断电保持 寿命"},
        {"项目名称": "信号联锁关系全场景智能测试平台搭建及应用", "关键词": "信号 联锁 测试 平台 覆盖"},
        {"项目名称": "数智溯・时钟源切换诊断平台", "关键词": "时钟源 GPS 1588 切换 日志"},
        {"项目名称": "站台门吊挂轮新防护材料升级项目", "关键词": "站台门 吊挂轮 耐磨 材料"},
    ]
    阈值 = 0.62

    def 相似度(甲: str, 乙: str) -> float:
        甲词 = set(re.findall(r"[\u4e00-\u9fa5a-zA-Z0-9]{2,}", 甲))
        乙词 = set(re.findall(r"[\u4e00-\u9fa5a-zA-Z0-9]{2,}", 乙))
        if not 甲词 or not 乙词:
            return 0.0
        交 = len(甲词 & 乙词)
        return 交 / max(1, min(len(甲词), len(乙词)))

    可入库, 重复项目, 标记行 = [], [], []
    for p in 项目列表:
        名称 = p["项目名称"]
        摘要 = 名称 + " " + p["正文"][:3000]
        最佳匹配, 最佳分 = None, 0.0
        for q in 项目列表:
            if q is p:
                continue
            分 = 相似度(摘要, q["项目名称"] + " " + q["正文"][:3000])
            if 分 > 最佳分:
                最佳分, 最佳匹配 = 分, q
        for b in 库内项目:
            分 = 相似度(摘要, b["项目名称"] + " " + b["关键词"])
            if 分 > 最佳分:
                最佳分, 最佳匹配 = 分, b
        if 最佳分 >= 阈值 and 最佳匹配 is not None:
            重复项目.append({"项目名称": 名称, "相似度": round(最佳分 * 100), "疑似重复于": 最佳匹配["项目名称"]})
            标记行.append("【重复风险】" + 名称 + " —— 与「" + 最佳匹配["项目名称"] + "」相似度约" + str(round(最佳分 * 100)) + "%，需与提报人沟通确认")
        else:
            可入库.append({"项目名称": 名称, "摘要": p["正文"][:1500]})

    报告 = "查重结论：共解析项目 " + str(len(项目列表)) + " 个；无重复风险 " + str(len(可入库)) + " 个；存在重复风险 " + str(len(重复项目)) + " 个。\n"
    报告 += "（说明：当前为画布内置降级比对；正式版经MCP调用查重系统1419条库，部署后切换）\n"
    if 标记行:
        报告 += "重复标记：\n" + "\n".join(标记行)

    return {
        "clean_projects": 可入库,
        "dup_projects": 重复项目,
        "dup_flag_list": "\n".join(标记行) if 标记行 else "本批项目未发现重复风险",
        "project_count": len(项目列表),
        "dup_report": 报告,
    }

